window.LEX_DATA={"blocks":[{"roman":"I","start":1,"end":20,"title":"Derecho público","description":"Organización del Estado, potestades públicas y relaciones internacionales."},{"roman":"II","start":21,"end":36,"title":"Derecho privado","description":"Relaciones entre particulares, empresa, bienes, contratos y circulación jurídica."},{"roman":"III","start":37,"end":47,"title":"Derecho social","description":"Trabajo, seguridad social, familia, inclusión y protección de grupos."},{"roman":"IV","start":48,"end":60,"title":"Derecho procesal","description":"Vías, garantías, prueba, ejecución y métodos de solución de controversias."},{"roman":"V","start":61,"end":77,"title":"Derecho económico y empresarial","description":"Mercados, empresa, regulación, inversión y actividad económica organizada."},{"roman":"VI","start":78,"end":89,"title":"Derecho ambiental y recursos naturales","description":"Ambiente, sostenibilidad, actividades extractivas y recursos naturales."},{"roman":"VII","start":90,"end":102,"title":"Derecho tecnológico","description":"Sistemas digitales, datos, plataformas, ciberseguridad y tecnologías emergentes."},{"roman":"VIII","start":103,"end":122,"title":"Derechos sectoriales y especialidades","description":"Sectores regulados y actividades con problemas jurídicos propios."},{"roman":"IX","start":123,"end":138,"title":"Disciplinas complementarias","description":"Herramientas teóricas, empíricas, interpretativas y profesionales para estudiar el Derecho."}],"branches":[{"number":1,"name":"Derecho constitucional","block":"Derecho público","blockRoman":"I","focus":"Estudia la Constitución, los derechos fundamentales, la organización del Estado y el control de las normas y del poder.","case":"Caso de los 65 congresistas — Exp. 00006-2003-AI/TC, Tribunal Constitucional, 2003.","whatHappened":"Un grupo de congresistas cuestionó reglas parlamentarias sobre acusación constitucional y prerrogativas de altos funcionarios.","lesson":"La Constitución obliga también al Congreso: sus procedimientos políticos deben respetar competencias, garantías y límites constitucionales.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":2,"name":"Derecho administrativo","block":"Derecho público","blockRoman":"I","focus":"Regula la actuación de la Administración Pública, sus potestades, procedimientos, servicios y relaciones con las personas.","case":"Caso Huatuco — Exp. 05057-2013-PA/TC, Tribunal Constitucional, 2015.","whatHappened":"Una trabajadora contratada temporalmente solicitó reposición en una entidad pública alegando desnaturalización de sus contratos.","lesson":"El acceso estable al empleo público exige, como regla, concurso de méritos y plaza presupuestada; el precedente fue luego delimitado por la jurisprudencia.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":3,"name":"Derecho penal","block":"Derecho público","blockRoman":"I","focus":"Define delitos, penas, medidas de seguridad y límites del poder punitivo del Estado.","case":"Caso Fujimori por Barrios Altos y La Cantuta — Exp. AV 19-2001, Corte Suprema, 2009.","whatHappened":"La Sala Penal Especial juzgó al expresidente por asesinatos y desapariciones ejecutados por el Grupo Colina.","lesson":"La responsabilidad penal puede alcanzar a quien domina una organización y utiliza su estructura para ejecutar crímenes, aunque no actúe materialmente.","source":"Poder Judicial","sourceUrl":"https://www.pj.gob.pe/"},{"number":4,"name":"Derecho procesal","block":"Derecho público","blockRoman":"I","focus":"Estudia las reglas comunes para acudir a un juez, probar hechos, impugnar decisiones y obtener tutela efectiva.","case":"Castillo Petruzzi y otros vs. Perú — Corte Interamericana de Derechos Humanos, 1999.","whatHappened":"Civiles acusados de traición a la patria fueron procesados por jueces militares “sin rostro”, con serias restricciones de defensa.","lesson":"No basta con que exista un proceso: el tribunal debe ser competente, independiente e imparcial, y la defensa debe poder actuar realmente.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":5,"name":"Derecho tributario","block":"Derecho público","blockRoman":"I","focus":"Regula la creación, determinación, recaudación e impugnación de tributos y protege al contribuyente frente al poder fiscal.","case":"Caso Arbitrios de Miraflores — Exp. 00053-2004-PI/TC, Tribunal Constitucional, 2005.","whatHappened":"Se cuestionaron ordenanzas municipales que distribuían el costo de limpieza, parques y serenazgo sin criterios suficientemente vinculados al servicio.","lesson":"Una tasa debe financiar un servicio individualizable y distribuir su costo con criterios razonables; no puede funcionar como un impuesto encubierto.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":6,"name":"Derecho financiero público","block":"Derecho público","blockRoman":"I","focus":"Ordena los ingresos, gastos, endeudamiento, tesorería y control de los recursos del Estado.","case":"Poder Judicial vs. Poder Ejecutivo — Exp. 00004-2004-CC/TC, Tribunal Constitucional, 2004–2005.","whatHappened":"El Poder Judicial defendió su autonomía para formular su presupuesto frente a modificaciones del Ejecutivo.","lesson":"La autonomía financiera no elimina la coordinación ni la disciplina fiscal, pero impide vaciar las funciones constitucionales de un poder del Estado.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":7,"name":"Derecho presupuestario","block":"Derecho público","blockRoman":"I","focus":"Se ocupa de la elaboración, aprobación, ejecución y control del presupuesto público.","case":"Poder Judicial vs. Poder Ejecutivo — Exp. 00004-2004-CC/TC, Tribunal Constitucional, 2004–2005.","whatHappened":"El conflicto surgió por la reducción del proyecto presupuestal formulado por el Poder Judicial antes de su remisión al Congreso.","lesson":"El presupuesto traduce prioridades públicas, pero su elaboración debe respetar competencias, sustentación técnica, equilibrio fiscal y control democrático.","source":"Tribunal Constitucional","scopeNote":"Se reutiliza el caso porque aquí interesa específicamente el ciclo presupuestario; en el punto 6 interesa la autonomía financiera.","sourceUrl":"https://www.tc.gob.pe/"},{"number":8,"name":"Derecho internacional público","block":"Derecho público","blockRoman":"I","focus":"Regula las relaciones entre Estados, organizaciones internacionales y otros sujetos internacionales.","case":"Controversia marítima Perú vs. Chile — Corte Internacional de Justicia, 2014.","whatHappened":"Perú pidió delimitar la frontera marítima; la Corte examinó acuerdos, práctica estatal y derecho del mar para trazarla.","lesson":"Las fronteras y obligaciones internacionales se determinan mediante tratados, costumbre, conducta de los Estados y solución pacífica de controversias.","source":"Corte Internacional de Justicia","sourceUrl":"https://www.icj-cij.org/"},{"number":9,"name":"Derecho internacional de los derechos humanos","block":"Derecho público","blockRoman":"I","focus":"Establece obligaciones internacionales para respetar, proteger y garantizar la dignidad y los derechos de las personas.","case":"Barrios Altos vs. Perú — Corte Interamericana de Derechos Humanos, 2001.","whatHappened":"Víctimas de una ejecución perpetrada por el Grupo Colina enfrentaron leyes de amnistía que impedían investigar y sancionar a los responsables.","lesson":"Las autoamnistías para graves violaciones son incompatibles con la Convención Americana y carecen de efectos jurídicos.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":10,"name":"Derecho electoral","block":"Derecho público","blockRoman":"I","focus":"Regula elecciones, partidos, candidaturas, sufragio, justicia electoral y legitimidad de la representación.","case":"Lizana Puelles — Exp. 05854-2005-PA/TC, Tribunal Constitucional, 2005.","whatHappened":"Un alcalde vacado cuestionó una decisión del Jurado Nacional de Elecciones y sostuvo que había vulnerado derechos fundamentales.","lesson":"La autonomía de la justicia electoral no crea zonas exentas de Constitución; sus actos pueden controlarse de manera excepcional ante lesiones manifiestas.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":11,"name":"Derecho parlamentario","block":"Derecho público","blockRoman":"I","focus":"Estudia la organización del Congreso, el procedimiento legislativo, el control político y las prerrogativas parlamentarias.","case":"Caso de los 65 congresistas — Exp. 00006-2003-AI/TC, Tribunal Constitucional, 2003.","whatHappened":"El proceso permitió precisar antejuicio, juicio político, inmunidad y garantías de altos funcionarios.","lesson":"Las potestades parlamentarias tienen finalidades distintas y no pueden confundirse ni ejercerse sin debido procedimiento.","source":"Tribunal Constitucional","scopeNote":"Se reutiliza el caso desde el ángulo de las instituciones parlamentarias.","sourceUrl":"https://www.tc.gob.pe/"},{"number":12,"name":"Derecho municipal y regional","block":"Derecho público","blockRoman":"I","focus":"Regula la autonomía, competencias, ordenanzas, servicios y coordinación de gobiernos locales y regionales.","case":"Ordenanzas regionales sobre hoja de coca — Exps. 00020 y 00021-2005-PI/TC, Tribunal Constitucional, 2005.","whatHappened":"Gobiernos regionales declararon patrimonio cultural a la hoja de coca y regularon aspectos reservados a políticas nacionales.","lesson":"La autonomía territorial se ejerce dentro de la Constitución y no permite invadir competencias exclusivas del Estado nacional.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":13,"name":"Derecho militar y policial","block":"Derecho público","blockRoman":"I","focus":"Regula la organización, disciplina, deberes y responsabilidad de las Fuerzas Armadas y la Policía.","case":"Reforma de la justicia militar — Exp. 00017-2003-AI/TC, Tribunal Constitucional, 2004.","whatHappened":"Se impugnaron normas que extendían el fuero militar y estructuraban órganos jurisdiccionales castrenses.","lesson":"El fuero militar es excepcional y solo conoce delitos de función; no puede sustituir a la justicia ordinaria en violaciones comunes o de derechos humanos.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":14,"name":"Derecho penitenciario","block":"Derecho público","blockRoman":"I","focus":"Regula la ejecución de penas, el régimen carcelario, la resocialización y los derechos de las personas privadas de libertad.","case":"Penal Miguel Castro Castro vs. Perú — Corte Interamericana de Derechos Humanos, 2006.","whatHappened":"Un operativo estatal en el penal produjo muertes, lesiones y tratos crueles contra internos, incluidas mujeres.","lesson":"La prisión restringe la libertad, no la dignidad: el Estado es garante de la vida, salud e integridad de quienes están bajo su custodia.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":15,"name":"Derecho aduanero","block":"Derecho público","blockRoman":"I","focus":"Regula el ingreso y salida de mercancías, su clasificación, valoración, origen, tributos y control fronterizo.","case":"Van Gend en Loos — asunto 26/62, Tribunal de Justicia de la Unión Europea, 1963.","whatHappened":"Una empresa impugnó el aumento de un derecho aduanero aplicado a un producto importado entre Estados miembros.","lesson":"Las reglas aduaneras pueden generar derechos directamente invocables cuando son claras; clasificar y gravar mercancías exige respetar el marco supranacional aplicable.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente comparado de integración europea; no es vinculante para el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":16,"name":"Derecho migratorio","block":"Derecho público","blockRoman":"I","focus":"Regula ingreso, permanencia, expulsión, refugio, nacionalidad y derechos de personas migrantes.","case":"Familia Pacheco Tineo vs. Bolivia — Corte Interamericana de Derechos Humanos, 2013.","whatHappened":"Una familia solicitante de refugio fue expulsada de forma sumaria hacia el Perú sin examen adecuado del riesgo.","lesson":"Toda devolución exige procedimiento, evaluación individual y respeto del principio de no devolución cuando existe peligro para la persona.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":17,"name":"Derecho diplomático y consular","block":"Derecho público","blockRoman":"I","focus":"Regula misiones diplomáticas, consulados, inmunidades y asistencia del Estado a sus nacionales en el extranjero.","case":"Jadhav — India vs. Pakistán, Corte Internacional de Justicia, 2019.","whatHappened":"Pakistán condenó a un ciudadano indio sin informarle oportunamente su derecho a comunicación y asistencia consular.","lesson":"La notificación consular es una garantía concreta: el Estado receptor debe informar y permitir acceso sin demora.","source":"Corte Internacional de Justicia","sourceUrl":"https://www.icj-cij.org/"},{"number":18,"name":"Derecho de la integración","block":"Derecho público","blockRoman":"I","focus":"Estudia los ordenamientos creados por procesos de integración y su relación con el derecho interno.","case":"Van Gend en Loos — asunto 26/62, Tribunal de Justicia de la Unión Europea, 1963.","whatHappened":"El tribunal resolvió si una norma del tratado podía ser invocada por una empresa ante un juez nacional.","lesson":"Un sistema de integración puede crear un orden jurídico propio con normas de efecto directo, según sus tratados y jurisprudencia.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Ejemplo europeo útil para comparar con la Comunidad Andina; no traslada automáticamente sus reglas al Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":19,"name":"Derecho penal internacional","block":"Derecho público","blockRoman":"I","focus":"Persigue responsabilidad individual por genocidio, crímenes de lesa humanidad, guerra y agresión.","case":"Fiscal vs. Thomas Lubanga Dyilo — ICC-01/04-01/06, Corte Penal Internacional, 2012.","whatHappened":"Lubanga fue juzgado por reclutar y utilizar a menores de quince años en un conflicto armado en la República Democrática del Congo.","lesson":"Los máximos responsables pueden responder personalmente ante tribunales internacionales por crímenes que afectan a la comunidad internacional.","source":"Corte Penal Internacional","sourceUrl":"https://www.icc-cpi.int/"},{"number":20,"name":"Derecho internacional humanitario","block":"Derecho público","blockRoman":"I","focus":"Limita los medios y métodos de guerra y protege a quienes no participan o dejaron de participar en hostilidades.","case":"Fiscal vs. Duško Tadić — IT-94-1-AR72, Tribunal Penal para la ex Yugoslavia, 1995.","whatHappened":"El tribunal examinó crímenes cometidos durante un conflicto interno en Bosnia y su propia competencia.","lesson":"Las reglas humanitarias esenciales también rigen conflictos armados no internacionales; la etiqueta interna no elimina la protección.","source":"Tribunal Penal Internacional para la ex Yugoslavia","sourceUrl":"https://www.icty.org/"},{"number":21,"name":"Derecho civil","block":"Derecho privado","blockRoman":"II","focus":"Regula personas, obligaciones, contratos, bienes, responsabilidad civil, familia y sucesiones entre particulares.","case":"Caso Choropampa–Yanacocha — I Pleno Casatorio Civil, Cas. 1465-2007-Cajamarca, Corte Suprema, 2008.","whatHappened":"Tras un derrame de mercurio, pobladores demandaron indemnización pese a haber celebrado transacciones extrajudiciales.","lesson":"La autonomía privada puede resolver controversias, pero su validez y efectos deben analizarse con cuidado cuando están en juego daños y asimetrías.","source":"Poder Judicial","sourceUrl":"https://www.pj.gob.pe/"},{"number":22,"name":"Derecho comercial","block":"Derecho privado","blockRoman":"II","focus":"Regula actos y contratos de comercio, empresarios, circulación de riqueza y operaciones del mercado.","case":"Minas Arirahua — Cas. 3899-2007-Lima y Exp. 01203-2010-PA/TC.","whatHappened":"Una controversia societaria y cambiaria discutió quién podía obligar válidamente a la empresa mediante títulos y representación.","lesson":"En el tráfico mercantil importan la apariencia, los poderes inscritos y la diligencia de quien contrata con una sociedad.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":23,"name":"Derecho empresarial","block":"Derecho privado","blockRoman":"II","focus":"Integra las reglas que afectan la creación, operación, contratación, financiamiento y responsabilidad de la empresa.","case":"Caso Pura Vida — Res. 159-2017/CCD y 2623-2018/SPC-INDECOPI.","whatHappened":"El producto se ofrecía con imágenes y denominaciones asociadas a leche pese a que su composición y categoría regulatoria eran distintas.","lesson":"La estrategia comercial debe alinear producto, etiqueta, publicidad, regulación sanitaria y expectativas razonables del consumidor.","source":"Indecopi","sourceUrl":"https://www.gob.pe/indecopi"},{"number":24,"name":"Derecho societario","block":"Derecho privado","blockRoman":"II","focus":"Regula constitución, órganos, capital, acuerdos, reorganización y disolución de sociedades.","case":"Minas Arirahua — Cas. 3899-2007-Lima y Exp. 01203-2010-PA/TC.","whatHappened":"El litigio giró en torno a actos realizados en nombre de la sociedad y a la extensión de las facultades representativas.","lesson":"Una sociedad actúa mediante órganos y representantes; por eso estatuto, poderes e inscripción registral son centrales para atribuir efectos.","source":"Tribunal Constitucional","scopeNote":"Se reutiliza el caso desde la representación societaria, no desde la circulación mercantil general.","sourceUrl":"https://www.tc.gob.pe/"},{"number":25,"name":"Derecho corporativo","block":"Derecho privado","blockRoman":"II","focus":"Se ocupa del gobierno, control, deberes de directores, grupos empresariales, fusiones y relaciones con inversionistas.","case":"BTI 2014 LLC vs. Sequana S.A. — [2022] UKSC 25.","whatHappened":"Tras pagos de dividendos, se discutió cuándo los directores deben considerar los intereses de acreedores ante una insolvencia próxima.","lesson":"La gestión corporativa cambia cuando la insolvencia deja de ser remota: el director debe ponderar a quienes soportan el riesgo económico.","source":"Supreme Court of the United Kingdom","scopeNote":"Precedente comparado; no es vinculante para el Perú.","sourceUrl":"https://www.supremecourt.uk/"},{"number":26,"name":"Derecho concursal","block":"Derecho privado","blockRoman":"II","focus":"Ordena la reestructuración o liquidación de deudores insolventes y la satisfacción colectiva de acreedores.","case":"Procedimiento concursal de Doe Run Perú — Indecopi, desde 2010.","whatHappened":"La crisis financiera y ambiental de la empresa llevó a sus acreedores a decidir entre reestructuración y liquidación.","lesson":"La insolvencia se resuelve colectivamente: los acreedores evalúan viabilidad, prioridades y activos bajo reglas comunes.","source":"Indecopi","scopeNote":"Es un procedimiento emblemático compuesto por múltiples decisiones, no una sola sentencia.","sourceUrl":"https://www.gob.pe/indecopi"},{"number":27,"name":"Derecho bancario","block":"Derecho privado","blockRoman":"II","focus":"Regula entidades financieras, captación, créditos, deberes de seguridad y supervisión prudencial.","case":"Philipp vs. Barclays Bank UK PLC — [2023] UKSC 25.","whatHappened":"Una clienta ordenó transferencias a estafadores; se discutió si el banco debía negarse pese a instrucciones válidas.","lesson":"El banco debe ejecutar mandatos autorizados, pero puede tener deberes de recuperación o alerta según las circunstancias y el marco aplicable.","source":"Supreme Court of the United Kingdom","scopeNote":"Precedente comparado; la respuesta peruana depende de regulación y deberes locales de idoneidad y seguridad.","sourceUrl":"https://www.supremecourt.uk/"},{"number":28,"name":"Derecho financiero privado","block":"Derecho privado","blockRoman":"II","focus":"Regula operaciones de crédito, inversión, garantías, derivados y estructuración financiera entre particulares.","case":"Quiebra de Lehman Brothers Holdings Inc. — Case 08-13555, Bankruptcy Court, Nueva York, 2008.","whatHappened":"La caída de la entidad activó miles de contratos financieros y reclamaciones transfronterizas durante la crisis global.","lesson":"La innovación financiera necesita reglas de riesgo, garantías, transparencia y resolución ordenada porque los efectos pueden ser sistémicos.","source":"U.S. Bankruptcy Court, Southern District of New York","scopeNote":"Caso extranjero de referencia mundial; no es precedente peruano.","sourceUrl":"https://www.nysb.uscourts.gov/"},{"number":29,"name":"Derecho de seguros","block":"Derecho privado","blockRoman":"II","focus":"Regula contratos de seguro, riesgo, prima, siniestro, cobertura, exclusiones y supervisión.","case":"FCA vs. Arch Insurance — [2021] UKSC 1.","whatHappened":"Miles de negocios reclamaron cobertura por interrupciones causadas por la pandemia de COVID-19 bajo pólizas con textos distintos.","lesson":"La solución depende de interpretar exactamente cobertura, exclusiones y causalidad; pequeñas diferencias contractuales cambian el resultado.","source":"Supreme Court of the United Kingdom","scopeNote":"Precedente comparado; no sustituye la Ley del Contrato de Seguro ni la jurisprudencia peruana.","sourceUrl":"https://www.supremecourt.uk/"},{"number":30,"name":"Derecho del mercado de valores","block":"Derecho privado","blockRoman":"II","focus":"Regula oferta pública, intermediación, información, emisores, fondos y protección del inversionista.","case":"SEC vs. W. J. Howey Co. — 328 U.S. 293, Corte Suprema de EE. UU., 1946.","whatHappened":"La empresa vendía parcelas de cítricos junto con contratos para cultivarlas y repartir rendimientos.","lesson":"Una operación puede ser valor mobiliario por su realidad económica aunque tenga otra etiqueta contractual.","source":"Supreme Court of the United States","scopeNote":"Precedente extranjero; útil por su influencia comparada, no vinculante en el Perú.","sourceUrl":"https://www.supremecourt.gov/"},{"number":31,"name":"Derecho cambiario","block":"Derecho privado","blockRoman":"II","focus":"Regula títulos valores como letra, pagaré y cheque, sus requisitos y acciones de cobro.","case":"Pagaré y fecha de vencimiento — Exp. 04087-2011-PA/TC, Tribunal Constitucional, 2012.","whatHappened":"El proceso discutió la ejecución de un pagaré y la relevancia de sus requisitos formales.","lesson":"Los títulos valores facilitan el crédito porque incorporan derechos, pero su fuerza depende del cumplimiento de las formalidades legales.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":32,"name":"Derecho notarial","block":"Derecho privado","blockRoman":"II","focus":"Regula la función del notario, instrumentos públicos, fe pública, escrituras y asuntos no contenciosos.","case":"Demandas contra el Decreto Legislativo 1049 — Exps. 00009, 00015 y 00029-2009-PI/TC, 2010.","whatHappened":"Colegios de notarios impugnaron varias reglas de la nueva Ley del Notariado.","lesson":"La función notarial es privada en su ejercicio, pero satisface interés público y está sujeta a regulación, igualdad y razonabilidad.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":33,"name":"Derecho registral","block":"Derecho privado","blockRoman":"II","focus":"Regula la publicidad jurídica, inscripción, prioridad, legitimación y oponibilidad de derechos.","case":"VII Pleno Casatorio Civil — Cas. 3671-2014-Lima, Corte Suprema, 2015.","whatHappened":"Se enfrentaron un derecho de propiedad no inscrito y un embargo inscrito sobre el mismo inmueble.","lesson":"El registro reduce incertidumbre, pero su relación con derechos anteriores exige aplicar reglas de prioridad, buena fe y naturaleza del derecho.","source":"Poder Judicial","sourceUrl":"https://www.pj.gob.pe/"},{"number":34,"name":"Derecho inmobiliario","block":"Derecho privado","blockRoman":"II","focus":"Integra propiedad, posesión, compraventa, arrendamiento, construcción, registro y financiamiento de inmuebles.","case":"IV Pleno Casatorio Civil — Cas. 2195-2011-Ucayali, Corte Suprema, 2013.","whatHappened":"Un propietario pidió desalojo y la Corte precisó cuándo la ocupación se considera precaria.","lesson":"La precariedad no se reduce a “no tener contrato”: debe examinarse si existe un título vigente que justifique la posesión.","source":"Poder Judicial","sourceUrl":"https://www.pj.gob.pe/"},{"number":35,"name":"Derecho internacional privado","block":"Derecho privado","blockRoman":"II","focus":"Resuelve qué juez, qué ley y qué reconocimiento corresponden en relaciones privadas conectadas con varios países.","case":"Exequátur — Cas. 660-2016-Arequipa, Corte Suprema.","whatHappened":"Se solicitó reconocer en el Perú una decisión extranjera y se evaluaron requisitos formales y orden público.","lesson":"El exequátur no repite el juicio de fondo: verifica competencia, firmeza, defensa y compatibilidad básica antes de dar efectos internos.","source":"Poder Judicial","sourceUrl":"https://www.pj.gob.pe/"},{"number":36,"name":"Derecho de la propiedad intelectual","block":"Derecho privado","blockRoman":"II","focus":"Protege marcas, patentes, derechos de autor, diseños, secretos empresariales y competencia asociada.","case":"Marca EBEL — Proceso 114-IP-2003, Tribunal de Justicia de la Comunidad Andina.","whatHappened":"El tribunal interpretó reglas andinas sobre registro, distintividad y riesgo de confusión entre signos.","lesson":"La marca protege origen empresarial, pero se deniega cuando el signo carece de distintividad o confunde con derechos previos.","source":"Tribunal de Justicia de la Comunidad Andina","sourceUrl":"https://www.tribunalandino.org.ec/"},{"number":37,"name":"Derecho laboral","block":"Derecho social","blockRoman":"III","focus":"Regula trabajo subordinado, contratación, remuneración, jornada, despido, sindicatos y negociación colectiva.","case":"Baylón Flores — Exp. 00206-2005-PA/TC, Tribunal Constitucional, 2005.","whatHappened":"Un trabajador cuestionó su despido mediante amparo y el TC delimitó cuándo esa vía era procedente.","lesson":"La protección laboral exige identificar el derecho afectado y la vía idónea; no todo conflicto de trabajo corresponde al proceso constitucional.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":38,"name":"Derecho procesal laboral","block":"Derecho social","blockRoman":"III","focus":"Regula la solución judicial de conflictos laborales con oralidad, inmediación, carga probatoria y tutela urgente.","case":"Baylón Flores — Exp. 00206-2005-PA/TC, Tribunal Constitucional, 2005.","whatHappened":"El caso separó controversias laborales constitucionales de las que requieren debate probatorio en la vía ordinaria.","lesson":"Elegir bien el proceso es sustancial: define prueba, plazos, oralidad y tipo de tutela que el juez puede conceder.","source":"Tribunal Constitucional","scopeNote":"Se reutiliza el caso por su aporte a la selección de la vía procesal laboral.","sourceUrl":"https://www.tc.gob.pe/"},{"number":39,"name":"Derecho de la seguridad social","block":"Derecho social","blockRoman":"III","focus":"Regula pensiones, salud, prestaciones y mecanismos solidarios frente a vejez, invalidez, enfermedad y otras contingencias.","case":"Reforma del régimen del Decreto Ley 20530 — Exps. acumulados 00050-2004-AI/TC y otros, 2005.","whatHappened":"Se impugnó una reforma constitucional y legal que cerró y modificó un régimen pensionario especial.","lesson":"Los derechos pensionarios tienen contenido protegido, pero los sistemas pueden reformarse por sostenibilidad si se respetan dignidad, igualdad y núcleo esencial.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":40,"name":"Derecho agrario social","block":"Derecho social","blockRoman":"III","focus":"Protege relaciones de trabajo, acceso a tierra y organización social vinculadas a la actividad rural.","case":"Bonos de la deuda agraria — Exp. 00022-1996-AI/TC, Tribunal Constitucional, 2001.","whatHappened":"Expropiaciones de la reforma agraria fueron pagadas con bonos cuyo valor se erosionó por la inflación.","lesson":"La transformación agraria persigue fines sociales, pero la expropiación exige compensación justa y preservación razonable del valor.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":41,"name":"Derecho cooperativo","block":"Derecho social","blockRoman":"III","focus":"Regula organizaciones de propiedad y gestión común creadas para satisfacer necesidades de sus socios.","case":"Expulsión de socio de cooperativa — Exp. 03794-2017-PA/TC, Tribunal Constitucional.","whatHappened":"Un socio fue separado automáticamente sin oportunidad suficiente de defensa frente a la imputación.","lesson":"La autonomía cooperativa no elimina el debido proceso: sancionar a un socio exige cargos claros, defensa y decisión motivada.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":42,"name":"Derecho de familia","block":"Derecho social","blockRoman":"III","focus":"Regula matrimonio, uniones, filiación, alimentos, cuidado, patrimonio familiar y ruptura de vínculos.","case":"Shols Pérez — Exp. 09332-2006-PA/TC, Tribunal Constitucional, 2007–2008.","whatHappened":"Un club negó un carné familiar a una hijastra porque no era hija biológica del socio.","lesson":"La familia constitucional incluye realidades ensambladas; el Derecho no debe invisibilizar vínculos de cuidado estables por un criterio exclusivamente biológico.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":43,"name":"Derecho de la niñez y adolescencia","block":"Derecho social","blockRoman":"III","focus":"Protege integralmente a niñas, niños y adolescentes bajo el principio de interés superior y autonomía progresiva.","case":"“Niños de la Calle” — Villagrán Morales y otros vs. Guatemala, Corte Interamericana, 1999.","whatHappened":"Cinco jóvenes en situación de calle fueron secuestrados, torturados y asesinados; el Estado no los protegió ni investigó eficazmente.","lesson":"El derecho a la vida exige condiciones dignas de existencia y protección reforzada cuando el niño está expuesto a violencia y exclusión.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":44,"name":"Derecho de las personas con discapacidad","block":"Derecho social","blockRoman":"III","focus":"Garantiza igualdad, accesibilidad, capacidad jurídica, apoyos, inclusión y ajustes razonables.","case":"Olmstead vs. L.C. — 527 U.S. 581, Corte Suprema de EE. UU., 1999.","whatHappened":"Dos mujeres permanecían institucionalizadas pese a que profesionales recomendaban atención en la comunidad.","lesson":"La segregación injustificada puede ser discriminatoria; los servicios deben favorecer vida independiente e inclusión cuando sea razonable.","source":"Supreme Court of the United States","scopeNote":"Precedente comparado; en el Perú deben aplicarse la Convención y la legislación nacional.","sourceUrl":"https://www.supremecourt.gov/"},{"number":45,"name":"Derecho de los pueblos indígenas","block":"Derecho social","blockRoman":"III","focus":"Protege identidad, territorio, consulta, autodeterminación interna y participación de pueblos originarios.","case":"Comunidad Nativa Tres Islas — Exp. 01126-2011-PHC/TC, Tribunal Constitucional, 2012.","whatHappened":"La comunidad restringió el ingreso de terceros vinculados con actividades que afectaban su territorio y seguridad.","lesson":"El territorio indígena no es solo suelo: sostiene autonomía, identidad y subsistencia, y permite controlar accesos dentro del marco constitucional.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":46,"name":"Derecho pensionario","block":"Derecho social","blockRoman":"III","focus":"Se especializa en adquisición, cálculo, reajuste, pago y defensa de pensiones.","case":"Cinco Pensionistas vs. Perú — Corte Interamericana de Derechos Humanos, 2003.","whatHappened":"Pensionistas reclamaron por la reducción de montos reconocidos y el incumplimiento prolongado de sentencias internas.","lesson":"La pensión consolidada integra el patrimonio y su afectación arbitraria, junto con el desacato judicial, puede generar responsabilidad internacional.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":47,"name":"Derecho de la protección social","block":"Derecho social","blockRoman":"III","focus":"Organiza políticas y prestaciones para enfrentar pobreza, enfermedad, dependencia y vulnerabilidad durante el ciclo de vida.","case":"Poblete Vilches y otros vs. Chile — Corte Interamericana de Derechos Humanos, 2018.","whatHappened":"Un adulto mayor recibió atención hospitalaria deficiente, sin información suficiente ni consideración adecuada de su vulnerabilidad.","lesson":"Los servicios sociales y sanitarios deben ser accesibles, informados y reforzados para personas en especial situación de riesgo.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":48,"name":"Derecho procesal civil","block":"Derecho procesal","blockRoman":"IV","focus":"Regula los procesos sobre obligaciones, contratos, propiedad, familia y demás relaciones privadas.","case":"I Pleno Casatorio Civil — Cas. 1465-2007-Cajamarca, Corte Suprema, 2008.","whatHappened":"En la demanda por el derrame de mercurio se discutió la excepción basada en una transacción extrajudicial previa.","lesson":"Las defensas procesales deben reflejar correctamente los efectos del negocio jurídico y permitir una decisión coherente sobre el fondo.","source":"Poder Judicial","scopeNote":"Se reutiliza el caso para explicar la interacción entre transacción y proceso civil.","sourceUrl":"https://www.pj.gob.pe/"},{"number":49,"name":"Derecho procesal penal","block":"Derecho procesal","blockRoman":"IV","focus":"Regula investigación, acusación, juicio, prueba, medidas coercitivas y garantías frente a una imputación penal.","case":"Castillo Petruzzi y otros vs. Perú — Corte Interamericana, 1999.","whatHappened":"Los acusados fueron sometidos a justicia militar secreta y enfrentaron obstáculos severos para conocer y controvertir la acusación.","lesson":"El proceso penal debe equilibrar eficacia y libertad mediante juez competente, contradicción, defensa, publicidad y presunción de inocencia.","source":"Corte Interamericana de Derechos Humanos","scopeNote":"Se reutiliza el caso por sus estándares procesales penales.","sourceUrl":"https://www.corteidh.or.cr/"},{"number":50,"name":"Derecho procesal constitucional","block":"Derecho procesal","blockRoman":"IV","focus":"Regula amparo, hábeas corpus, hábeas data, cumplimiento, inconstitucionalidad y conflictos competenciales.","case":"Anicama Hernández — Exp. 01417-2005-PA/TC, Tribunal Constitucional, 2005.","whatHappened":"Un pensionista acudió al amparo y el TC precisó qué parte del derecho a la pensión recibe protección urgente.","lesson":"El amparo protege el contenido constitucional directamente afectado; no reemplaza toda vía ordinaria ni revisa cualquier desacuerdo legal.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":51,"name":"Derecho procesal administrativo","block":"Derecho procesal","blockRoman":"IV","focus":"Ordena la impugnación de actos estatales y el proceso contencioso-administrativo.","case":"Salazar Yarlenque — Exp. 03741-2004-PA/TC, Tribunal Constitucional, 2006.","whatHappened":"Una municipalidad exigió pagar una tasa para admitir un recurso administrativo.","lesson":"El acceso a impugnar no puede condicionarse con barreras irrazonables; la Administración debe respetar legalidad y debido procedimiento.","source":"Tribunal Constitucional","scopeNote":"El criterio de control difuso administrativo de esta sentencia fue posteriormente dejado sin efecto; permanece valiosa su doctrina sobre barreras y defensa.","sourceUrl":"https://www.tc.gob.pe/"},{"number":52,"name":"Derecho procesal laboral","block":"Derecho procesal","blockRoman":"IV","focus":"Diseña la vía judicial específica para pretensiones laborales y de seguridad social.","case":"Elgo Ríos — Exp. 02383-2013-PA/TC, Tribunal Constitucional, 2015.","whatHappened":"Un trabajador acudió al amparo y el TC fijó criterios para saber cuándo otra vía es “igualmente satisfactoria”.","lesson":"La procedencia depende de estructura, tutela, riesgo de irreparabilidad y urgencia; no basta afirmar que existe otro proceso.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":53,"name":"Derecho procesal tributario","block":"Derecho procesal","blockRoman":"IV","focus":"Regula fiscalización, reclamación, apelación, prueba y control judicial en controversias fiscales.","case":"Icatom S.A. — Exp. 04532-2013-PA/TC, Tribunal Constitucional.","whatHappened":"La controversia examinó intereses moratorios acumulados mientras la Administración demoraba más allá del plazo legal en resolver.","lesson":"El contribuyente no debe soportar intereses atribuibles a retrasos estatales excesivos; también en materia tributaria rige el plazo razonable.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":54,"name":"Derecho procesal de familia","block":"Derecho procesal","blockRoman":"IV","focus":"Regula procesos de alimentos, filiación, tenencia, visitas, adopción y violencia familiar con tutela reforzada.","case":"Fornerón e hija vs. Argentina — Corte Interamericana de Derechos Humanos, 2012.","whatHappened":"La demora judicial consolidó la separación entre un padre biológico y su hija, entregada a otra familia.","lesson":"En asuntos de niñez, el tiempo decide derechos: la diligencia debe ser excepcional para evitar que la demora vuelva irreversible la separación.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":55,"name":"Derecho procesal electoral","block":"Derecho procesal","blockRoman":"IV","focus":"Regula impugnaciones, plazos, prueba y garantías en controversias electorales.","case":"Lizana Puelles — Exp. 05854-2005-PA/TC, Tribunal Constitucional, 2005.","whatHappened":"La vacancia de un alcalde planteó la tensión entre definitividad electoral y tutela de derechos.","lesson":"La rapidez y cierre de etapas son esenciales, pero no autorizan decisiones arbitrarias ni inmunes a la Constitución.","source":"Tribunal Constitucional","scopeNote":"Se reutiliza el caso desde las garantías y vías del proceso electoral.","sourceUrl":"https://www.tc.gob.pe/"},{"number":56,"name":"Derecho procesal militar-policial","block":"Derecho procesal","blockRoman":"IV","focus":"Regula investigación y juzgamiento de delitos de función dentro de un fuero excepcional.","case":"Durand y Ugarte vs. Perú — Corte Interamericana de Derechos Humanos, 2000.","whatHappened":"La justicia militar intervino en hechos vinculados con muertes y desapariciones durante un motín penitenciario.","lesson":"Las violaciones de derechos humanos y delitos comunes contra civiles corresponden a la justicia ordinaria, no al fuero militar.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":57,"name":"Derecho probatorio","block":"Derecho procesal","blockRoman":"IV","focus":"Estudia admisibilidad, actuación, valoración y carga de la prueba en todo tipo de procesos.","case":"R.N. 1912-2005-Piura y Acuerdo Plenario 01-2006/ESV-22, Corte Suprema.","whatHappened":"La condena se apoyó en indicios y la Corte sistematizó sus requisitos de pluralidad, conexión y razonamiento.","lesson":"La prueba indiciaria es válida si los hechos base están acreditados y la inferencia es lógica, convergente y explicada.","source":"Poder Judicial","sourceUrl":"https://www.pj.gob.pe/"},{"number":58,"name":"Derecho de ejecución","block":"Derecho procesal","blockRoman":"IV","focus":"Regula el cumplimiento forzado de sentencias, laudos, conciliaciones y otros títulos ejecutivos.","case":"Acevedo Buendía y otros (“Cesantes y Jubilados de la Contraloría”) vs. Perú — Corte Interamericana, 2009.","whatHappened":"El Estado incumplió durante años sentencias que ordenaban pagos pensionarios.","lesson":"La tutela judicial no termina con una sentencia favorable: el cumplimiento oportuno forma parte del derecho de acceso a justicia.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":59,"name":"Derecho arbitral","block":"Derecho procesal","blockRoman":"IV","focus":"Regula el convenio arbitral, competencia de árbitros, procedimiento, laudo, anulación y ejecución.","case":"Cantuarias Salaverry — Exp. 06167-2005-PHC/TC, Tribunal Constitucional, 2006.","whatHappened":"Un árbitro cuestionó la persecución penal derivada de decisiones tomadas en un arbitraje.","lesson":"El arbitraje tiene naturaleza jurisdiccional y autonomía para decidir su competencia, pero debe respetar derechos fundamentales y control judicial posterior.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":60,"name":"Mecanismos alternativos de solución de conflictos","block":"Derecho procesal","blockRoman":"IV","focus":"Comprende negociación, conciliación, mediación y otros métodos para resolver disputas sin sentencia tradicional.","case":"Acta de conciliación y ejecución — Exp. 02340-2013-PA/TC, Tribunal Constitucional, 2013.","whatHappened":"La controversia trató el cumplimiento judicial de obligaciones contenidas en un acta conciliatoria.","lesson":"El acuerdo conciliatorio puede tener fuerza ejecutiva; su redacción debe ser clara, exigible y respetuosa de derechos indisponibles.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":61,"name":"Derecho económico","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Estudia la Constitución económica, la intervención estatal y las libertades de mercado.","case":"Roberto Nesta Brero y más de 5,000 ciudadanos — Exp. 00008-2003-AI/TC, 2003.","whatHappened":"Los demandantes cuestionaron normas sobre espectáculos taurinos y el TC desarrolló el modelo económico constitucional.","lesson":"La economía social de mercado combina iniciativa privada con intervención estatal razonable para bienestar, consumidores y competencia.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":62,"name":"Derecho de la competencia","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Previene carteles, abuso de dominio y concentraciones que dañan el proceso competitivo.","case":"Cártel de farmacias — Exp. 008-2010/CLC, Res. 0738-2017/SDC-INDECOPI.","whatHappened":"Cadenas de farmacias coordinaron precios de medicamentos mediante mecanismos que incluían información canalizada por un proveedor.","lesson":"Un acuerdo anticompetitivo puede probarse sin comunicación directa entre todos los participantes; importan patrón, coordinación y efectos.","source":"Indecopi","sourceUrl":"https://www.gob.pe/indecopi"},{"number":63,"name":"Derecho del consumidor","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Protege información, seguridad, elección, idoneidad, trato justo y reparación del destinatario final.","case":"Agua Pura Rovic S.A.C. — Exp. 03315-2004-AA/TC, Tribunal Constitucional, 2005.","whatHappened":"Una empresa cuestionó una medida relacionada con la protección de consumidores y el TC interpretó el artículo 65 constitucional.","lesson":"El consumidor es destinatario del modelo económico y el Estado debe corregir asimetrías mediante información, seguridad y tutela efectiva.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":64,"name":"Derecho publicitario","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Controla publicidad engañosa, desleal, discriminatoria y la responsabilidad de quienes la difunden.","case":"Anuncio “Modo Cama” de Saga Falabella–Circus Grey — Res. 107-2019/CCD-INDECOPI.","whatHappened":"La campaña utilizó una escena humorística que la autoridad consideró reproductora de estereotipos racistas.","lesson":"La creatividad comercial tiene límites: una pieza puede infringir la adecuación social aunque alegue humor o intención no discriminatoria.","source":"Indecopi","sourceUrl":"https://www.gob.pe/indecopi"},{"number":65,"name":"Derecho de la regulación económica","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Estudia reguladores, servicios públicos, tarifas, acceso a redes y límites de las competencias administrativas.","case":"Gas Point S.A.C. vs. Municipalidad de Pueblo Libre — Exp. 02373-2023-PA/TC, Sent. 18/2025.","whatHappened":"Una controversia sobre una estación de servicio enfrentó competencias municipales y regulación sectorial.","lesson":"Cada autoridad debe actuar dentro de sus atribuciones; la especialización regulatoria no elimina legalidad, motivación ni debido procedimiento.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":66,"name":"Derecho de contrataciones del Estado","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Regula selección de proveedores, ejecución contractual, integridad, competencia y uso del dinero público.","case":"Ley de Promoción Temporal del Desarrollo Productivo Nacional — Exp. 00018-2003-AI/TC, 2004.","whatHappened":"Se cuestionó una bonificación en compras públicas para bienes y servicios producidos en el país.","lesson":"Las preferencias estatales deben perseguir una finalidad legítima, ser temporales y respetar igualdad y competencia.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":67,"name":"Derecho de asociaciones público-privadas","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Regula concesiones, financiamiento, asignación de riesgos y relación de largo plazo entre Estado e inversionista.","case":"Metro de Lima Línea 2 S.A. vs. República del Perú — CIADI ARB/17/3, laudo de 2024.","whatHappened":"El concesionario y el Estado litigaron obligaciones vinculadas con una megaobra de transporte.","lesson":"Una APP requiere definir con precisión hitos, entrega de áreas, riesgos, cambios y mecanismos de solución de controversias.","source":"CIADI","scopeNote":"La ficha oficial confirma el expediente y sus actuaciones; no se atribuye aquí un resultado específico sin desarrollar el laudo completo.","sourceUrl":"https://icsid.worldbank.org/"},{"number":68,"name":"Derecho del comercio internacional","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Regula OMC, aranceles, tratados, defensas comerciales y restricciones al intercambio transfronterizo.","case":"Perú — Derecho adicional sobre productos agropecuarios — OMC DS457, Guatemala vs. Perú, 2015.","whatHappened":"Guatemala cuestionó el sistema peruano de franja de precios aplicado a determinadas importaciones agrícolas.","lesson":"Una política comercial interna debe respetar los compromisos multilaterales sobre aranceles y agricultura.","source":"Organización Mundial del Comercio","sourceUrl":"https://www.wto.org/"},{"number":69,"name":"Derecho de la inversión extranjera","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Regula protección, trato, expropiación y arbitraje de inversiones provenientes de otro Estado.","case":"Bear Creek Mining Corporation vs. República del Perú — CIADI ARB/14/21, 2017.","whatHappened":"La revocación de derechos vinculados al proyecto minero Santa Ana generó una reclamación bajo el tratado con Canadá.","lesson":"La acción estatal puede generar responsabilidad internacional; la conducta social y ambiental del inversionista también puede influir en el análisis del daño.","source":"CIADI","sourceUrl":"https://icsid.worldbank.org/"},{"number":70,"name":"Derecho de startups","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Integra constitución, inversión, innovación, propiedad intelectual, plataformas y trabajo en empresas emergentes.","case":"Uber BV vs. Aslam — [2021] UKSC 5.","whatHappened":"Conductores reclamaron derechos laborales pese a contratos que los describían como independientes.","lesson":"La realidad operativa pesa más que la etiqueta contractual: control sobre precio, cliente y prestación puede revelar subordinación.","source":"Supreme Court of the United Kingdom","scopeNote":"Precedente comparado, no vinculante en el Perú.","sourceUrl":"https://www.supremecourt.uk/"},{"number":71,"name":"Derecho del comercio electrónico","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Regula contratos digitales, marketplaces, pagos, información y responsabilidad de intermediarios.","case":"L’Oréal y otros vs. eBay — C-324/09, Tribunal de Justicia de la Unión Europea, 2011.","whatHappened":"Titulares de marcas reclamaron por productos ilícitos vendidos a través de la plataforma.","lesson":"Un marketplace puede asumir mayor responsabilidad si desempeña un papel activo o conoce ilícitos y no actúa diligentemente.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente comparado; la responsabilidad peruana depende de su propio marco civil, de consumo e intelectual.","sourceUrl":"https://curia.europa.eu/"},{"number":72,"name":"Derecho del compliance","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Diseña sistemas empresariales para prevenir, detectar, investigar y responder a incumplimientos.","case":"Cártel de farmacias — Res. 0738-2017/SDC-INDECOPI.","whatHappened":"Además de sancionar la concertación, la autoridad dispuso implementar un programa de cumplimiento en libre competencia.","lesson":"Un programa útil parte de riesgos reales, controles verificables, formación, canal de reporte y respuesta; no es un documento decorativo.","source":"OCDE — comunicación oficial del Perú","scopeNote":"Se reutiliza el caso por la medida correctiva de cumplimiento, no por la prueba del cártel.","sourceUrl":"https://www.oecd.org/"},{"number":73,"name":"Derecho penal económico","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Persigue delitos cometidos en actividades económicas, como lavado, fraude, corrupción y delitos tributarios.","case":"Jader Hare Rizgallah Garib — Cas. 92-2017-Arequipa y Sentencia Plenaria Casatoria 1-2017/CIJ-433.","whatHappened":"La Corte debatió qué debe acreditarse respecto de la actividad criminal previa en el lavado de activos.","lesson":"Un precedente debe leerse con su evolución: la doctrina inicial perdió carácter vinculante y fue reemplazada por una decisión plenaria posterior.","source":"Poder Judicial","sourceUrl":"https://www.pj.gob.pe/"},{"number":74,"name":"Derecho tributario empresarial","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Aplica impuestos, fiscalización, sanciones y litigación fiscal a la actividad de las empresas.","case":"Telefónica del Perú S.A.A. — Exp. 02152-2022-PA/TC, Sent. 72/2024.","whatHappened":"La empresa acudió al amparo para cuestionar aspectos de una controversia tributaria compleja.","lesson":"El amparo no es una instancia fiscal adicional; normalmente corresponde la vía contencioso-administrativa salvo lesión constitucional urgente.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":75,"name":"Derecho de franquicias","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Regula licencia de marca y know-how, asistencia, uniformidad de red y restricciones entre franquiciante y franquiciado.","case":"Pronuptia de Paris — asunto 161/84, Tribunal de Justicia de la Unión Europea, 1986.","whatHappened":"Una red de vestidos de novia impuso obligaciones a sus franquiciados y se discutió su compatibilidad con la competencia.","lesson":"Son válidas restricciones indispensables para proteger know-how e identidad de red, no las que eliminan competencia sin justificación.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Caso europeo clásico; no es vinculante en el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":76,"name":"Derecho de la construcción","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Regula contratos de obra, diseño, cronogramas, adicionales, defectos, garantías y disputas técnicas.","case":"Metro de Lima Línea 2 S.A. vs. Perú — CIADI ARB/17/3, 2017–2024.","whatHappened":"La ejecución de la megaobra produjo controversias dentro del contrato de concesión.","lesson":"En construcción, la claridad sobre áreas, hitos, cambios, riesgos y retrasos evita que un problema técnico se convierta en disputa jurídica mayor.","source":"CIADI","scopeNote":"Se reutiliza el expediente desde la gestión jurídica de una megaobra.","sourceUrl":"https://icsid.worldbank.org/"},{"number":77,"name":"Derecho de logística y transporte","block":"Derecho económico y empresarial","blockRoman":"V","focus":"Regula transporte de carga y pasajeros, almacenaje, cadena logística, infraestructura y responsabilidad.","case":"Transportistas de carga de Áncash–Zona Sierra — Res. 056-2011/CLC-INDECOPI.","whatHappened":"Decenas de transportistas concertaron fletes y reparto de clientes alegando costos referenciales del MTC.","lesson":"Una referencia estatal de costos no autoriza acuerdos privados de precios ni reparto de mercado.","source":"Indecopi","scopeNote":"La publicación institucional reseña la decisión inicial y advertía entonces una apelación pendiente.","sourceUrl":"https://www.gob.pe/indecopi"},{"number":78,"name":"Derecho ambiental","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Previene, controla y repara daños al ambiente y articula información, participación y justicia ambiental.","case":"Habitantes de La Oroya vs. Perú — Corte Interamericana de Derechos Humanos, 2023.","whatHappened":"Décadas de contaminación metalúrgica afectaron salud, ambiente y vida de habitantes sin respuesta estatal suficiente.","lesson":"El Estado debe regular, fiscalizar, informar y remediar eficazmente; ambiente sano y salud son derechos exigibles.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":79,"name":"Derecho minero","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula concesiones, permisos, impactos, fiscalización, cierre y relaciones comunitarias de la minería.","case":"Proyecto Conga — Exp. 00001-2012-PI/TC, Tribunal Constitucional, 2012.","whatHappened":"Una ordenanza regional declaró inviable un proyecto de gran minería y pretendió dejar sin efecto decisiones nacionales.","lesson":"Las competencias mineras y ambientales se distribuyen por ley; la falta regional de competencia no elimina deberes de prevención ni diálogo.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":80,"name":"Derecho energético","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula generación, transmisión, distribución, tarifas, contratos e inversión en energía.","case":"Duke Energy International Peru Investments No. 1 Ltd. vs. Perú — CIADI ARB/03/28, 2008.","whatHappened":"Una inversión eléctrica reclamó por el alcance de compromisos contractuales y de estabilidad asumidos por el Estado.","lesson":"Las garantías de estabilidad deben interpretarse con precisión: no cubren más de lo pactado, pero su incumplimiento puede generar responsabilidad.","source":"CIADI","sourceUrl":"https://icsid.worldbank.org/"},{"number":81,"name":"Derecho de hidrocarburos","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula exploración, explotación, transporte, refinación, comercialización y seguridad de petróleo y gas.","case":"Derrame de La Pampilla — Informe 00026-2022-OEFA/DEAM-STEC.","whatHappened":"El derrame de petróleo de enero de 2022 afectó litoral, fauna y actividades económicas, activando evaluación y medidas estatales.","lesson":"El operador debe prevenir, comunicar, contener, evaluar y remediar; un derrame puede generar responsabilidades administrativas, civiles y penales.","source":"OEFA","scopeNote":"Es una investigación técnica oficial dentro de varios procedimientos, no una sentencia única.","sourceUrl":"https://www.gob.pe/oefa"},{"number":82,"name":"Derecho forestal","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Protege bosques y fauna silvestre mediante zonificación, títulos habilitantes, control y sanción.","case":"Ley 31973, llamada “Ley Antiforestal” — Exps. 00002, 00003 y 00005-2024-PI/TC, 2025.","whatHappened":"Se cuestionaron reglas que suspendían exigencias de zonificación y afectaban territorios y recursos forestales.","lesson":"El TC anuló disposiciones transitorias por amenaza ambiental y falta de consulta respecto de comunidades expresamente afectadas.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":83,"name":"Derecho de aguas","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula dominio, uso, licencias, cuencas, calidad y solución de conflictos por recursos hídricos.","case":"Proyecto Majes Siguas II — Exp. 01939-2011-PA/TC, Tribunal Constitucional, 2011.","whatHappened":"Una suspensión indefinida del proyecto enfrentó necesidades hídricas y ambientales de Cusco y Arequipa.","lesson":"La decisión hídrica exige información técnica definitiva y ponderación de ambiente, agua, trabajo y desarrollo, no paralización indefinida.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":84,"name":"Derecho pesquero","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula acceso, cuotas, vedas, flota, fiscalización y sostenibilidad de recursos hidrobiológicos.","case":"Límites máximos de captura de anchoveta — Exps. 00026 y 00028-2008-PI/TC, 2010.","whatHappened":"Se impugnó el sistema de cuotas individuales establecido por el Decreto Legislativo 1084.","lesson":"Las cuotas pueden compatibilizar libertad de empresa y competencia con la obligación de evitar depredación del recurso.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":85,"name":"Derecho agrario","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula propiedad y uso rural, producción agraria, expropiación, comunidades y financiamiento del campo.","case":"Bonos de la deuda agraria — Exp. 00022-1996-AI/TC, Tribunal Constitucional, 2001.","whatHappened":"Los bonos usados para pagar expropiaciones perdieron valor real durante años de inflación.","lesson":"La indemnización expropiatoria no puede volverse simbólica; debe preservarse un valor compatible con la garantía de propiedad.","source":"Tribunal Constitucional","scopeNote":"Se reutiliza desde la regulación patrimonial agraria; el punto 40 enfatiza la dimensión social.","sourceUrl":"https://www.tc.gob.pe/"},{"number":86,"name":"Derecho de la biodiversidad","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Protege especies, ecosistemas, áreas naturales, servicios ambientales y recursos genéticos.","case":"Área de Conservación Regional Cordillera Escalera — Exp. 03343-2007-PA/TC, 2009.","whatHappened":"Actividades de hidrocarburos proyectadas dentro del área protegida generaron una demanda ambiental.","lesson":"La actividad económica debe ser compatible con objetivos de conservación, plan maestro y evaluación ambiental.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":87,"name":"Derecho del cambio climático","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula mitigación, adaptación, emisiones, transición energética y justicia intergeneracional.","case":"Neubauer y otros — 1 BvR 2656/18 y acumulados, Tribunal Constitucional Federal alemán, 2021.","whatHappened":"Jóvenes cuestionaron una ley que posponía gran parte del esfuerzo de reducción de emisiones hacia el futuro.","lesson":"Trasladar cargas climáticas excesivas puede restringir libertades futuras; la trayectoria de reducción debe ser suficientemente clara.","source":"Tribunal Constitucional Federal de Alemania","scopeNote":"Precedente comparado; no es vinculante en el Perú.","sourceUrl":"https://www.bundesverfassungsgericht.de/"},{"number":88,"name":"Derecho de los recursos naturales","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula titularidad nacional, concesiones, regalías y aprovechamiento sostenible de recursos.","case":"Ley de Regalía Minera — Exp. 00048-2004-PI/TC, Tribunal Constitucional, 2005.","whatHappened":"Empresas cuestionaron la regalía exigida por aprovechar recursos minerales.","lesson":"El recurso natural es patrimonio de la Nación; la concesión otorga un derecho condicionado al interés público y la regalía es contraprestación.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":89,"name":"Derecho de protección y bienestar animal","block":"Derecho ambiental y recursos naturales","blockRoman":"VI","focus":"Regula deberes de cuidado, prohibición de crueldad y usos científicos, productivos o culturales de animales.","case":"Excepción taurina y gallística de la Ley 30407 — Exp. 00022-2018-PI/TC, Sent. 556/2020.","whatHappened":"Se pidió anular la excepción que permite corridas de toros y peleas de gallos.","lesson":"El caso mostró la tensión entre bienestar animal y prácticas culturales; no hubo cinco votos para expulsar la excepción legal.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":90,"name":"Derecho informático","block":"Derecho tecnológico","blockRoman":"VII","focus":"Estudia los efectos jurídicos del software, sistemas de información, acceso informático y tratamiento automatizado.","case":"Van Buren vs. United States — No. 19-783, Corte Suprema de EE. UU., 2021.","whatHappened":"Un policía consultó una base de datos autorizada con un fin indebido y fue acusado de exceder acceso informático.","lesson":"La autorización técnica y el uso indebido no son siempre lo mismo; los delitos informáticos requieren límites precisos para evitar criminalización excesiva.","source":"Supreme Court of the United States","scopeNote":"Precedente comparado, no vinculante en el Perú.","sourceUrl":"https://www.supremecourt.gov/"},{"number":91,"name":"Derecho digital","block":"Derecho tecnológico","blockRoman":"VII","focus":"Integra identidad, datos, plataformas, contenidos, contratación y derechos fundamentales en entornos digitales.","case":"Google Spain y Google Inc. vs. AEPD y Costeja — C-131/12, TJUE, 2014.","whatHappened":"Un ciudadano pidió retirar de resultados de búsqueda enlaces antiguos sobre una deuda ya resuelta.","lesson":"Los buscadores tratan datos y pueden tener que desindexar resultados cuando privacidad y actualidad pesan más que el interés público.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo; el alcance peruano depende de la legislación nacional de datos y libertad de información.","sourceUrl":"https://curia.europa.eu/"},{"number":92,"name":"Derecho de internet","block":"Derecho tecnológico","blockRoman":"VII","focus":"Regula acceso, intermediarios, contenidos, libertad de expresión, responsabilidad y neutralidad en la red.","case":"Packingham vs. North Carolina — No. 15-1194, Corte Suprema de EE. UU., 2017.","whatHappened":"Una ley prohibía a ciertos condenados acceder a amplias redes sociales, incluso para actividades cotidianas.","lesson":"Internet es un espacio central de expresión; las restricciones generales deben superar un examen riguroso de necesidad y proporcionalidad.","source":"Supreme Court of the United States","scopeNote":"Precedente comparado, no vinculante en el Perú.","sourceUrl":"https://www.supremecourt.gov/"},{"number":93,"name":"Derecho de protección de datos personales","block":"Derecho tecnológico","blockRoman":"VII","focus":"Regula recolección, uso, conservación, transferencia y derechos sobre información identificable.","case":"Schrems II — C-311/18, Tribunal de Justicia de la Unión Europea, 2020.","whatHappened":"Se cuestionó la transferencia de datos de Facebook desde Europa a Estados Unidos por acceso de autoridades públicas.","lesson":"Transferir datos al extranjero exige protección esencialmente equivalente y mecanismos eficaces frente a vigilancia incompatible.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo de referencia; no es vinculante en el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":94,"name":"Derecho de la ciberseguridad","block":"Derecho tecnológico","blockRoman":"VII","focus":"Asigna deberes de prevención, gestión, notificación y responsabilidad frente a incidentes digitales.","case":"FTC vs. Wyndham Worldwide Corp. — No. 14-3514, Corte de Apelaciones del Tercer Circuito, 2015.","whatHappened":"Brechas sucesivas expusieron datos de clientes y la autoridad alegó prácticas de seguridad deficientes.","lesson":"La seguridad prometida debe corresponder con controles reales; fallas previsibles pueden generar responsabilidad regulatoria y contractual.","source":"Federal Trade Commission","sourceUrl":"https://www.ftc.gov/"},{"number":95,"name":"Derecho de la inteligencia artificial","block":"Derecho tecnológico","blockRoman":"VII","focus":"Regula diseño, uso, transparencia, discriminación, seguridad y responsabilidad de sistemas de IA.","case":"State vs. Loomis — 2016 WI 68, Corte Suprema de Wisconsin.","whatHappened":"Un juez utilizó la puntuación algorítmica COMPAS al sentenciar, pese a que el acusado no podía conocer el modelo propietario completo.","lesson":"Una herramienta de riesgo no debe decidir por sí sola; su uso exige advertencias, límites, explicación y control humano.","source":"Wisconsin Courts","scopeNote":"Precedente comparado; no vinculante en el Perú.","sourceUrl":"https://www.wicourts.gov/"},{"number":96,"name":"Derecho de plataformas digitales","block":"Derecho tecnológico","blockRoman":"VII","focus":"Regula intermediación, gobernanza, trabajo, competencia y responsabilidad de plataformas.","case":"Asociación Profesional Élite Taxi vs. Uber Systems Spain — C-434/15, TJUE, 2017.","whatHappened":"Se discutió si Uber era solo un servicio digital o parte integral del transporte urbano.","lesson":"La etiqueta tecnológica no decide la regulación: si la plataforma controla elementos esenciales, puede quedar sujeta al régimen del servicio subyacente.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente comparado, no vinculante en el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":97,"name":"Derecho de telecomunicaciones","block":"Derecho tecnológico","blockRoman":"VII","focus":"Regula redes, espectro, licencias, interconexión, usuarios, competencia y privacidad de comunicaciones.","case":"Digital Rights Ireland — C-293/12 y C-594/12, TJUE, 2014.","whatHappened":"Una directiva obligaba a conservar de manera general metadatos de comunicaciones de toda la población.","lesson":"La seguridad no justifica retención masiva e indiferenciada sin límites, control y relación con una amenaza concreta.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo; no vinculante en el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":98,"name":"Derecho del comercio electrónico transfronterizo","block":"Derecho tecnológico","blockRoman":"VII","focus":"Se concentra en servicios digitales ofrecidos entre países, ley aplicable y deberes de intermediación.","case":"Airbnb Ireland — C-390/18, Tribunal de Justicia de la Unión Europea, 2019.","whatHappened":"Francia pretendía aplicar a Airbnb exigencias propias de agentes inmobiliarios sin notificación europea previa.","lesson":"La clasificación del servicio digital determina qué reglas nacionales pueden aplicarse y cómo coordinar mercados transfronterizos.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Se distingue del punto 71 por el énfasis transfronterizo y regulatorio.","sourceUrl":"https://curia.europa.eu/"},{"number":99,"name":"Derecho de criptoactivos y blockchain","block":"Derecho tecnológico","blockRoman":"VII","focus":"Regula tokens, intercambios, custodia, prevención de lavado, contratos inteligentes y tributación.","case":"Skatteverket vs. Hedqvist — C-264/14, Tribunal de Justicia de la Unión Europea, 2015.","whatHappened":"Un operador quería cambiar bitcoins por moneda tradicional y consultó el tratamiento del IVA.","lesson":"La calificación jurídica depende de la función económica del criptoactivo; el tribunal trató el cambio de bitcoin como servicio financiero exento.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo tributario; no define por sí solo la regulación peruana.","sourceUrl":"https://curia.europa.eu/"},{"number":100,"name":"Derecho de la robótica y sistemas autónomos","block":"Derecho tecnológico","blockRoman":"VII","focus":"Analiza seguridad, control, atribución de decisiones y responsabilidad por máquinas autónomas.","case":"Atropello mortal por vehículo autónomo de Uber en Tempe — investigación NTSB HWY18MH010, 2018–2019.","whatHappened":"Un vehículo de prueba en modo automatizado atropelló a Elaine Herzberg; la investigación examinó sistema, operador y cultura de seguridad.","lesson":"En sistemas autónomos la responsabilidad exige reconstruir diseño, supervisión humana, alertas, organización y decisiones del operador.","source":"National Transportation Safety Board","scopeNote":"Es una investigación técnica oficial, no una sentencia judicial.","sourceUrl":"https://www.ntsb.gov/"},{"number":101,"name":"Derecho de la prueba digital","block":"Derecho tecnológico","blockRoman":"VII","focus":"Regula obtención, preservación, autenticidad, integridad y valoración de evidencia electrónica.","case":"Riley vs. California — No. 13-132, Corte Suprema de EE. UU., 2014.","whatHappened":"La policía registró sin orden el teléfono de una persona detenida y utilizó su contenido como prueba.","lesson":"Un teléfono concentra enorme información personal; su registro exige garantías reforzadas y cadena de custodia verificable.","source":"Supreme Court of the United States","scopeNote":"Precedente comparado; en Perú rigen la Constitución y las reglas procesales nacionales.","sourceUrl":"https://www.supremecourt.gov/"},{"number":102,"name":"Derecho penal informático","block":"Derecho tecnológico","blockRoman":"VII","focus":"Tipifica acceso ilícito, fraude, interferencia, suplantación y otros ataques contra sistemas y datos.","case":"Van Buren vs. United States — No. 19-783, Corte Suprema de EE. UU., 2021.","whatHappened":"El acusado tenía acceso autorizado a la base, pero la consultó para un propósito prohibido.","lesson":"La legalidad penal exige distinguir claramente acceso sin permiso de abuso de un permiso existente.","source":"Supreme Court of the United States","scopeNote":"Se reutiliza el caso por la interpretación penal del acceso informático.","sourceUrl":"https://www.supremecourt.gov/"},{"number":103,"name":"Derecho sanitario","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Organiza el sistema de salud, acceso, vigilancia epidemiológica, prestaciones y obligaciones estatales.","case":"Cuscul Pivaral y otros vs. Guatemala — Corte Interamericana de Derechos Humanos, 2018.","whatHappened":"Personas con VIH enfrentaron falta de atención, tratamiento y seguimiento adecuados durante años.","lesson":"El derecho a la salud exige disponibilidad, accesibilidad, aceptabilidad y calidad, con especial atención a grupos vulnerables.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":104,"name":"Derecho médico","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula relación clínica, consentimiento, responsabilidad profesional, historia médica y decisiones al final de la vida.","case":"Artavia Murillo y otros (“Fecundación in vitro”) vs. Costa Rica — Corte Interamericana, 2012.","whatHappened":"La prohibición absoluta de fecundación in vitro impidió a varias parejas acceder al tratamiento.","lesson":"La regulación médica debe respetar autonomía, vida privada, salud reproductiva e igualdad y superar un juicio de proporcionalidad.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":105,"name":"Derecho farmacéutico","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula investigación, patente, registro, fabricación, calidad, promoción y acceso a medicamentos.","case":"Novartis AG vs. Union of India — Civil Appeals 2706–2716/2013, Corte Suprema de India.","whatHappened":"Novartis buscó patentar una nueva forma de imatinib; la Corte aplicó un requisito reforzado de eficacia terapéutica.","lesson":"El sistema puede impedir extensiones artificiosas de exclusividad y equilibrar innovación con acceso a medicamentos.","source":"Supreme Court of India","scopeNote":"Precedente comparado, no vinculante en el Perú.","sourceUrl":"https://www.sci.gov.in/"},{"number":106,"name":"Derecho educativo","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula acceso, calidad, igualdad, convivencia, currículo y responsabilidades del sistema educativo.","case":"Brown vs. Board of Education — 347 U.S. 483, Corte Suprema de EE. UU., 1954.","whatHappened":"Niñas y niños afroamericanos eran obligados a asistir a escuelas segregadas por ley.","lesson":"Separar por raza produce desigualdad constitucional aunque instalaciones formales parezcan equivalentes.","source":"Library of Congress","scopeNote":"Precedente histórico comparado, no vinculante en el Perú.","sourceUrl":"https://www.loc.gov/"},{"number":107,"name":"Derecho universitario","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula autonomía, licenciamiento, calidad, gobierno, grados y relación entre universidad y Estado.","case":"Ley Universitaria 30220 — Exps. acumulados 00014-2014-PI/TC y otros, Tribunal Constitucional, 2015.","whatHappened":"Universidades y congresistas cuestionaron el sistema de supervisión y licenciamiento encabezado por Sunedu.","lesson":"La autonomía universitaria convive con el deber estatal de asegurar calidad y proteger a estudiantes dentro del marco examinado por la sentencia.","source":"Tribunal Constitucional","scopeNote":"El marco legal tuvo reformas posteriores; el caso debe leerse en su contexto normativo.","sourceUrl":"https://www.tc.gob.pe/"},{"number":108,"name":"Derecho deportivo","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula federaciones, clubes, deportistas, transferencias, disciplina, dopaje y explotación comercial.","case":"Bosman — C-415/93, Tribunal de Justicia de la Unión Europea, 1995.","whatHappened":"Un futbolista quedó limitado por reglas de transferencia y cuotas de nacionalidad al terminar su contrato.","lesson":"La autonomía deportiva no puede desconocer libre circulación y competencia cuando la actividad tiene dimensión económica.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo, no vinculante en el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":109,"name":"Derecho marítimo","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula navegación, buques, transporte, seguros, abordajes, salvamento y jurisdicción en el mar.","case":"M/V “Saiga” (No. 2) — Caso 2, Tribunal Internacional del Derecho del Mar, 1999.","whatHappened":"Guinea detuvo un buque de San Vicente y las Granadinas y usó fuerza durante su captura.","lesson":"El Estado de pabellón puede reclamar y la interdicción marítima debe respetar jurisdicción, necesidad y proporcionalidad.","source":"Tribunal Internacional del Derecho del Mar","sourceUrl":"https://www.itlos.org/"},{"number":110,"name":"Derecho aeronáutico","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula aeronaves, aeropuertos, transporte aéreo, seguridad, responsabilidad y derechos del pasajero.","case":"Sturgeon y otros — C-402/07 y C-432/07, TJUE, 2009.","whatHappened":"Pasajeros sufrieron retrasos prolongados y reclamaron compensación comparable a una cancelación.","lesson":"Un gran retraso puede causar una pérdida de tiempo indemnizable cuando la regulación reconoce protección equivalente.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo; en Perú rigen las normas nacionales y tratados aplicables.","sourceUrl":"https://curia.europa.eu/"},{"number":111,"name":"Derecho espacial","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula objetos espaciales, satélites, licencias, responsabilidad y uso pacífico del espacio ultraterrestre.","case":"Viasat, Inc. vs. FCC — Nos. 21-1123 y acumulados, D.C. Circuit, 2022.","whatHappened":"Empresas y organizaciones impugnaron autorizaciones para una constelación satelital y su evaluación ambiental.","lesson":"Las licencias espaciales combinan telecomunicaciones, seguridad, ambiente y legitimación para impugnar decisiones técnicas.","source":"Federal Communications Commission","scopeNote":"Caso administrativo comparado; no es precedente peruano ni un fallo internacional sobre responsabilidad espacial.","sourceUrl":"https://www.fcc.gov/"},{"number":112,"name":"Derecho del transporte","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula servicios, infraestructura, habilitaciones, seguridad, competencia y responsabilidad de transportistas.","case":"Élite Taxi vs. Uber — C-434/15, Tribunal de Justicia de la Unión Europea, 2017.","whatHappened":"La plataforma conectaba conductores no profesionales con pasajeros y controlaba elementos centrales del servicio.","lesson":"Cuando la intermediación forma una unidad con el transporte, puede quedar sujeta a autorización y regulación sectorial.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Se reutiliza desde la calificación del servicio de transporte.","sourceUrl":"https://curia.europa.eu/"},{"number":113,"name":"Derecho turístico","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula agencias, hospedaje, paquetes, información, seguridad y protección del viajero.","case":"Leitner vs. TUI Deutschland — C-168/00, Tribunal de Justicia de la Unión Europea, 2002.","whatHappened":"Una menor enfermó por alimentos durante un viaje combinado y la familia perdió el disfrute vacacional.","lesson":"El daño puede incluir la pérdida del disfrute del viaje, no solo gastos o lesiones físicas, según el régimen aplicable.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo, no vinculante en el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":114,"name":"Derecho alimentario","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula inocuidad, composición, etiquetado, trazabilidad, publicidad y responsabilidad sobre alimentos.","case":"Cassis de Dijon — asunto 120/78, Tribunal de Justicia de la Unión Europea, 1979.","whatHappened":"Alemania impidió vender un licor francés por no alcanzar su graduación mínima nacional.","lesson":"Los requisitos alimentarios deben proteger fines legítimos sin crear barreras desproporcionadas al comercio.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo de mercado interior; no vinculante en el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":115,"name":"Derecho del patrimonio cultural","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Protege bienes, lugares, expresiones y memoria cultural frente a destrucción, tráfico o uso incompatible.","case":"Ley 29164 y patrimonio cultural — Exp. 00003-2008-PI/TC, Tribunal Constitucional, 2010.","whatHappened":"Se cuestionó un régimen para inversión turística en bienes culturales y zonas aledañas.","lesson":"La inversión puede admitirse solo con salvaguardas reales de conservación, acceso e interés cultural.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":116,"name":"Derecho eclesiástico del Estado","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula libertad religiosa, neutralidad, cooperación y relación jurídica del Estado con confesiones.","case":"Lautsi y otros vs. Italia — Demanda 30814/06, Gran Sala del TEDH, 2011.","whatHappened":"Una madre cuestionó la presencia obligatoria de crucifijos en aulas públicas italianas.","lesson":"La relación entre símbolos, educación y neutralidad depende del contexto y del margen estatal, sin adoctrinamiento ni discriminación.","source":"Tribunal Europeo de Derechos Humanos","scopeNote":"Precedente europeo, no vinculante en el Perú.","sourceUrl":"https://www.echr.coe.int/"},{"number":117,"name":"Derecho funerario","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula destino, identificación, traslado, inhumación y exhumación de restos, cementerios y duelo digno.","case":"Victoria Vilca Torres — Exp. 01294-2020-PHC/TC, Tribunal Constitucional, 2021.","whatHappened":"Una madre buscó conocer y recuperar los restos de su hijo para darle sepultura digna.","lesson":"La incertidumbre sobre el destino de restos puede afectar dignidad, integridad y libertad de culto; el Estado debe facilitar verdad y sepultura.","source":"Tribunal Constitucional","scopeNote":"La decisión examinó la tutela constitucional del reclamo y su admisión; debe distinguirse del pronunciamiento definitivo sobre todos los hechos.","sourceUrl":"https://www.tc.gob.pe/"},{"number":118,"name":"Derecho de medios de comunicación","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula prensa, radiodifusión, libertad informativa, rectificación, honor y pluralismo.","case":"Herrera Ulloa vs. Costa Rica — Corte Interamericana de Derechos Humanos, 2004.","whatHappened":"Un periodista fue condenado por reproducir información extranjera sobre un funcionario diplomático.","lesson":"El debate sobre asuntos públicos recibe protección reforzada y las sanciones deben considerar diligencia, fuente y efecto inhibidor.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":119,"name":"Derecho del entretenimiento","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula producción y explotación de música, cine, eventos, videojuegos, contratos y derechos de autor.","case":"MGM Studios Inc. vs. Grokster, Ltd. — 545 U.S. 913, Corte Suprema de EE. UU., 2005.","whatHappened":"Servicios de intercambio de archivos promovían usos infractores de obras protegidas.","lesson":"Quien induce activamente la infracción puede responder aunque su tecnología admita usos lícitos.","source":"Library of Congress","scopeNote":"Precedente comparado, no vinculante en el Perú.","sourceUrl":"https://www.loc.gov/"},{"number":120,"name":"Derecho de la moda","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Integra marcas, diseños, autor, publicidad, contratos, trabajo y sostenibilidad de la industria de moda.","case":"Christian Louboutin vs. Van Haren — C-163/16, TJUE, 2018.","whatHappened":"Se discutió si una marca consistente en una suela roja era excluible por tratarse de una “forma”.","lesson":"Un color aplicado en una posición específica puede funcionar como signo distintivo y no quedar reducido a la forma del producto.","source":"Tribunal de Justicia de la Unión Europea","scopeNote":"Precedente europeo, no vinculante en el Perú.","sourceUrl":"https://curia.europa.eu/"},{"number":121,"name":"Derecho financiero del consumidor","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Protege al usuario de créditos, tarjetas, seguros y servicios financieros frente a cláusulas, costos y riesgos.","case":"Protección del consumidor financiero — Exp. 01238-2004-PA/TC, Tribunal Constitucional, 2005.","whatHappened":"El litigio permitió desarrollar el deber especial de información y protección en relaciones financieras asimétricas.","lesson":"La libertad contractual financiera convive con transparencia, idoneidad y control de cláusulas que colocan al usuario en desventaja injustificada.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":122,"name":"Derecho de la gestión del riesgo de desastres","block":"Derechos sectoriales y especialidades","blockRoman":"VIII","focus":"Regula prevención, preparación, respuesta, reconstrucción y responsabilidades frente a amenazas naturales o humanas.","case":"Budayeva y otros vs. Rusia — Tribunal Europeo de Derechos Humanos, 2008.","whatHappened":"Un alud de lodo previsible destruyó viviendas y causó muertes pese a advertencias previas sobre el riesgo.","lesson":"Cuando la autoridad conoce un peligro grave debe prevenir, informar, organizar respuesta e investigar las fallas.","source":"Tribunal Europeo de Derechos Humanos","scopeNote":"Precedente europeo, no vinculante en el Perú.","sourceUrl":"https://www.echr.coe.int/"},{"number":123,"name":"Filosofía del Derecho","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Reflexiona sobre justicia, validez, autoridad, derechos y relación entre Derecho y moral.","case":"Barrios Altos vs. Perú — Corte Interamericana, 2001.","whatHappened":"Leyes formalmente aprobadas impedían investigar una masacre estatal.","lesson":"Una norma puede existir formalmente y, sin embargo, ser jurídicamente incompatible con derechos superiores y exigencias de justicia.","source":"Corte Interamericana de Derechos Humanos","scopeNote":"Es una disciplina teórica, no una rama normativa autónoma.","sourceUrl":"https://www.corteidh.or.cr/"},{"number":124,"name":"Teoría general del Derecho","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Estudia conceptos comunes: norma, sistema, validez, fuentes, interpretación, sanción y relación jurídica.","case":"Lizana Puelles — Exp. 05854-2005-PA/TC, Tribunal Constitucional, 2005.","whatHappened":"La sentencia discutió cómo conviven una cláusula de definitividad electoral y la fuerza normativa de los derechos.","lesson":"El orden jurídico debe interpretarse como sistema: ninguna competencia pública queda fuera de la Constitución.","source":"Tribunal Constitucional","scopeNote":"Disciplina transversal; el caso funciona como ejemplo de sistema y jerarquía normativa.","sourceUrl":"https://www.tc.gob.pe/"},{"number":125,"name":"Historia del Derecho","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Explica cómo instituciones, normas y prácticas jurídicas cambian con su contexto político y social.","case":"Barrios Altos vs. Perú — Corte Interamericana, 2001.","whatHappened":"La decisión respondió a leyes de amnistía dictadas durante la transición desde un régimen autoritario.","lesson":"Comprender el contexto revela por qué ciertas instituciones cambian y cómo el Derecho responde a abusos del pasado.","source":"Corte Interamericana de Derechos Humanos","scopeNote":"La historia jurídica es una disciplina de estudio; el caso ilustra una transformación, no “pertenece” exclusivamente a ella.","sourceUrl":"https://www.corteidh.or.cr/"},{"number":126,"name":"Sociología jurídica","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Estudia cómo funciona realmente el Derecho en la sociedad y cómo influyen poder, desigualdad y cultura.","case":"González y otras (“Campo Algodonero”) vs. México — Corte Interamericana, 2009.","whatHappened":"Desapariciones y asesinatos de mujeres ocurrieron en un contexto de violencia y discriminación estructural en Ciudad Juárez.","lesson":"La respuesta jurídica eficaz exige mirar patrones sociales, no solo hechos aislados, y corregir prácticas institucionales que reproducen violencia.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":127,"name":"Antropología jurídica","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Analiza el Derecho desde culturas, comunidades, pluralismo y prácticas normativas diversas.","case":"Comunidad Nativa Tres Islas — Exp. 01126-2011-PHC/TC, Tribunal Constitucional, 2012.","whatHappened":"La comunidad defendió control territorial y organización propia frente al ingreso de terceros.","lesson":"El análisis intercultural entiende territorio y autoridad comunal según su significado colectivo, no solo desde categorías patrimoniales individuales.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":128,"name":"Psicología jurídica","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Aplica conocimiento psicológico a testimonio, trauma, capacidad, familia, conducta y decisiones judiciales.","case":"Atala Riffo y niñas vs. Chile — Corte Interamericana de Derechos Humanos, 2012.","whatHappened":"Una madre perdió el cuidado de sus hijas basándose en prejuicios sobre su orientación sexual y supuestos daños no demostrados.","lesson":"La evaluación de bienestar debe apoyarse en evidencia concreta, no en estereotipos presentados como conclusiones psicológicas.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":129,"name":"Criminología","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Estudia causas, patrones, control y prevención del delito y sus efectos sobre víctimas y sociedad.","case":"Campo Algodonero vs. México — Corte Interamericana, 2009.","whatHappened":"El caso reveló patrones repetidos de desaparición, violencia de género, impunidad y respuesta estatal deficiente.","lesson":"La prevención criminal requiere identificar patrones, factores de riesgo y fallas institucionales, no limitarse a castigar un hecho ya consumado.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":130,"name":"Criminalística","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Emplea técnicas científicas para localizar, fijar, recoger y analizar indicios de un hecho posiblemente delictivo.","case":"Selvi y otros vs. State of Karnataka — Corte Suprema de India, 2010.","whatHappened":"Se pretendió someter forzosamente a investigados a narcoanálisis, polígrafo y mapeo cerebral.","lesson":"La técnica forense debe ser válida, voluntaria cuando corresponda y compatible con integridad, no autoincriminación y fiabilidad probatoria.","source":"Supreme Court of India","scopeNote":"Precedente comparado, no vinculante en el Perú.","sourceUrl":"https://www.sci.gov.in/"},{"number":131,"name":"Medicina legal y ciencias forenses","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Aplica medicina y ciencias al examen de lesiones, muerte, identidad, toxicología y evidencia biológica.","case":"Campo Algodonero vs. México — Corte Interamericana, 2009.","whatHappened":"La investigación presentó deficiencias en levantamiento, autopsias, conservación e identificación de restos.","lesson":"Una falla forense puede destruir verdad y justicia; protocolos, trazabilidad y trato digno de restos son esenciales.","source":"Corte Interamericana de Derechos Humanos","sourceUrl":"https://www.corteidh.or.cr/"},{"number":132,"name":"Política criminal","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Diseña estrategias estatales de prevención, persecución, sanción y reinserción del delito.","case":"Legislación antiterrorista — Exp. 00010-2002-AI/TC, Tribunal Constitucional, 2003.","whatHappened":"Se impugnaron tipos penales, cadena perpetua y reglas procesales creadas para enfrentar el terrorismo.","lesson":"La gravedad del delito no elimina legalidad, proporcionalidad ni revisión judicial; la política criminal debe ser eficaz y constitucional.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":133,"name":"Argumentación jurídica","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Estudia cómo justificar decisiones mediante razones, pruebas, reglas, principios y respuesta a objeciones.","case":"Giuliana Llamoja — Exp. 00728-2008-PHC/TC, Tribunal Constitucional, 2008.","whatHappened":"Una condena basada en indicios fue cuestionada por no explicar suficientemente la inferencia hacia la responsabilidad.","lesson":"Motivar no es acumular frases: el juez debe hacer visible la cadena entre hechos probados, inferencias y conclusión.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":134,"name":"Hermenéutica jurídica","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Estudia métodos y límites para atribuir significado a normas, principios, precedentes y hechos.","case":"Lizana Puelles — Exp. 05854-2005-PA/TC, Tribunal Constitucional, 2005.","whatHappened":"El TC armonizó la definitividad de decisiones electorales con la protección constitucional de derechos.","lesson":"Interpretar exige unidad de la Constitución, concordancia práctica, corrección funcional y fuerza normativa, no lectura aislada de una frase.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":135,"name":"Metodología de la investigación jurídica","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Ordena la formulación de problemas, selección de fuentes, método, contraste y presentación de resultados jurídicos.","case":"Selvi y otros vs. State of Karnataka — Corte Suprema de India, 2010.","whatHappened":"El tribunal contrastó validez científica, evidencia disponible y efectos constitucionales de técnicas investigativas.","lesson":"Investigar jurídicamente exige definir la pregunta, jerarquizar fuentes, verificar evidencia y separar dato, inferencia y valoración.","source":"Supreme Court of India","scopeNote":"Disciplina metodológica; el caso es una ilustración del contraste entre ciencia, prueba y derechos.","sourceUrl":"https://www.sci.gov.in/"},{"number":136,"name":"Derecho comparado","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Compara ordenamientos para comprender soluciones, diferencias y posibles trasplantes jurídicos.","case":"Lautsi y otros vs. Italia — TEDH, 2011.","whatHappened":"La Gran Sala examinó diferentes modelos europeos sobre símbolos religiosos en escuelas y la falta de consenso uniforme.","lesson":"Comparar ayuda a identificar alternativas y contexto; una solución extranjera no se copia sin revisar Constitución, instituciones y cultura locales.","source":"Tribunal Europeo de Derechos Humanos","sourceUrl":"https://www.echr.coe.int/"},{"number":137,"name":"Análisis económico del Derecho","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Evalúa incentivos, costos, información y efectos de las reglas jurídicas sobre conductas y bienestar.","case":"Ley contra la usura — Exp. 00010-2021-PI/TC, Tribunal Constitucional, 2024.","whatHappened":"Se cuestionaron topes de interés y facultades del BCRP por sus efectos sobre protección del usuario y acceso al crédito.","lesson":"Una regla protectora debe considerar asimetría y abuso, pero también incentivos, oferta formal de crédito y posibles efectos no deseados.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"},{"number":138,"name":"Ética y deontología jurídica","block":"Disciplinas complementarias","blockRoman":"IX","focus":"Regula deberes profesionales de independencia, lealtad, secreto, diligencia, veracidad y trato digno.","case":"Disciplina por colegio profesional — Exp. 03954-2006-PA/TC, Tribunal Constitucional, 2007.","whatHappened":"Una sanción impuesta por un colegio profesional fue cuestionada por legalidad y garantías del procedimiento.","lesson":"La autorregulación ética es legítima, pero la sanción exige tipicidad, defensa, imparcialidad y motivación.","source":"Tribunal Constitucional","sourceUrl":"https://www.tc.gob.pe/"}]};